package com.examservice.infrastructure.persistence.entity;import com.examservice.domain.model.Difficulty;import jakarta.persistence.*;import java.util.UUID;@Entity@Table(name="exam_matrix_rules")public class MatrixRuleEntity{@Id public UUID id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="matrix_id",nullable=false)public MatrixEntity matrix;@Column(name="chapter_id",nullable=false)public UUID chapterId;@Column(name="topic_id")public UUID topicId;@Enumerated(EnumType.STRING)@Column(nullable=false)public Difficulty difficulty;@Column(name="question_count",nullable=false)public int questionCount;}
